def test_missing_and_malformed(self):
    with self.assertRaises(KeyError):
        resolve(DOC, "/users/5")
    with self.assertRaises(ValueError):
        resolve(DOC, "users")

def test_decodes_tilde_and_slash_in_keys(self):
    document = {"~1": "tilde-one", "a/b": "slash"}
    self.assertEqual(resolve(document, "/~01"), "tilde-one")
    self.assertEqual(resolve(document, "/a~1b"), "slash")
